const routes = { home:'Home', dashboard:'Dashboard', projects:'Projects', project:'Project Details', tasks:'Tasks', task:'Task Details', assistant:'AI Assistant', profile:'Profile / Settings', login:'Login', register:'Register' };
let aiMode = 'suggestions';
let aiState = { loading: false, loadingResources: false, loaded: false, error: '', projects: [], tasks: [], results: [], targetId: '' };
let aiResourceRequest = 0;
let themeMode = 'light';
try { themeMode = localStorage.getItem('taskflow-theme') === 'dark' ? 'dark' : 'light'; } catch {}
document.documentElement.dataset.theme = themeMode;
let authUser = null;
let authCheckPath = null;
let verifiedHash = null;
let authGeneration = 0;
const projectCache = new Map();
let dashboardCache = null;
let dashboardFilters = { project: '', range: 'week' };
let dashboardRequest = 0;
let projectSearchRequest = 0;
let projectSearchText = '';
let projectStatusFilter = 'all';
const taskCache = new Map();
const projectTaskCache = new Map();
let taskFilters = { q: '', status: '', priority: '', project: '', assignee: '' };
let taskSearchRequest = 0;
const API_BASE = ['localhost','127.0.0.1'].includes(location.hostname) && location.port && location.port !== '3000' ? `${location.protocol}//${location.hostname}:3000` : '';
const esc = (s='') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const go = (route, id='') => `#/${route}${id ? `/${encodeURIComponent(id)}` : ''}`;
const tag = (label, cls='') => `<span class="tag ${cls}">${esc(label)}</span>`;
const statusClass = s => ({'Done':'green','Completed':'green','In progress':'blue','In Progress':'blue','In review':'amber','On hold':'amber','To do':'','To Do':'','Planning':''}[s] || '');
const priorityClass = s => ({High:'rose',Medium:'amber',Low:''}[s] || '');
const taskProgress = task => task.status === 'Completed' ? 100 : Array.isArray(task.subtasks) ? (task.subtasks.length ? Math.round(task.subtasks.filter(subtask => subtask.completed).length / task.subtasks.length * 100) : 0) : Math.max(0, Math.min(100, Number(task.progress) || 0));
const taskProgressBar = task => { const value = taskProgress(task); return `<div class="task-progress-track" role="progressbar" aria-label="${value}% complete" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><span style="width:${value}%"></span></div>`; };
function taskProgressPanel(task){const progress=taskProgress(task),completed=task.subtasks.filter(subtask=>subtask.completed).length;const basis=task.subtasks.length?`${completed} of ${task.subtasks.length} subtasks complete`:(task.status==='Completed'?'Task completed':'Progress updates when this task is completed');return '<section class="task-progress-panel"><div class="task-progress-heading"><strong>Task completion</strong><span>'+progress+'%</span></div>'+taskProgressBar(task)+'<p class="task-progress-owner">'+esc(basis)+' · Assigned to '+esc(task.assignee?.name||'No one yet')+'</p></section>';}
const avatar = (s, cls='') => `<span class="avatar ${cls}">${esc(s)}</span>`;
function sidebar(route) {
  const assignedCount=dashboardCache?.data?.assignedTaskCount;
  const displayName=authUser?.name||'User';
  const links = [['dashboard','▦','Overview'],['projects','▣','Projects'],['tasks','☷','My tasks'],['assistant','✳','AI Assistant']];
  return `<aside class="sidebar" id="sidebar"><a class="brand" href="${go('home')}"><span class="brand-mark">t</span>taskflow</a><div class="workspace"><span class="workspace-icon">TF</span><span class="workspace-name">My workspace<span class="workspace-caption">${esc(authUser?.role||'')}</span></span></div><div class="nav-label">Workspace</div><nav class="nav-list">${links.map(([r,i,n])=>`<a class="nav-link ${route===r||route==='project'&&r==='projects'||route==='task'&&r==='tasks'?'active':''}" href="${go(r)}"><span class="nav-icon">${i}</span>${n}${r==='tasks'&&assignedCount!==undefined?`<span class="nav-count">${assignedCount}</span>`:''}</a>`).join('')}</nav><div class="nav-label">Personal</div><nav class="nav-list"><a class="nav-link ${route==='profile'?'active':''}" href="${go('profile')}"><span class="nav-icon">⚙</span>Settings</a></nav><div class="sidebar-bottom"><div class="upgrade-card"><strong>Make space for good work</strong><p>Keep your projects and priorities moving forward.</p><a href="${go('projects')}">Explore your workspace →</a></div><a class="user-chip" href="${go('profile')}">${avatar(displayName.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}<span><span class="user-name">${esc(displayName)}</span><span class="user-email">${esc(authUser?.email||'')}</span></span></a></div></aside>`;
}
function frame(route, body) { const displayName=authUser?.name||'User';return `<div class="shell">${sidebar(route)}<main class="main"><header class="topbar"><div class="breadcrumb-wrap"><button class="mobile-menu" aria-label="Open navigation" onclick="toggleSidebar()">☰</button><div class="breadcrumb">Workspace <span style="padding:0 6px;color:#c2c6ce">/</span> <strong>${routes[route]||'TaskFlow'}</strong></div></div><div class="top-actions"><button class="icon-button theme-toggle" id="theme-toggle" type="button" aria-label="Switch to ${themeMode==='dark'?'light':'dark'} mode" title="Switch to ${themeMode==='dark'?'light':'dark'} mode" onclick="toggleTheme()">${themeMode==='dark'?'☀':'☾'}</button><span class="top-avatar">${esc(displayName.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><button class="button" type="button" id="logout-button">Sign out</button></div></header><section class="content">${body}</section></main></div>`; }
function pageHead(title, sub, action='') { return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`; }
function projectCard(p) { const members=p.members||[],date=p.deadline?formatProjectDate(p.deadline,{month:'short',day:'numeric'}):'No deadline';return `<article class="card project-card" data-search="${esc((p.name+' '+(p.description||'')+' '+p.status).toLowerCase())}"><div class="project-card-head"><span class="project-symbol">${esc(p.name.slice(0,1).toUpperCase())}</span>${tag(p.status,statusClass(p.status))}</div><a href="${go('project',p.id)}"><h3>${esc(p.name)}</h3></a><p>${esc(p.description||'No description yet.')}</p><div class="card-foot"><span>${members.length+1} ${members.length===0?'person':'people'} · Due ${esc(date)}</span><span class="avatars">${members.slice(0,3).map((m,i)=>avatar(initials(m.name),['','purple','teal'][i%3])).join('')}</span></div></article>`; }
function dashboardTaskRows(group) {
  if (!group?.tasks?.length) return '<div class="empty-state">No tasks in this status.</div>';
  return `<div class="dashboard-task-list">${group.tasks.slice(0,4).map(task=>`<a class="dashboard-task" href="${go('task',task.id)}"><span class="task-name">${esc(task.title)}</span><span class="task-sub">${esc(task.project.name)} · ${esc(task.assignee?.name||'Unassigned')} · ${task.dueDate?formatProjectDate(task.dueDate,{month:'short',day:'numeric'}):'No due date'}</span><span class="task-progress-summary">${taskProgress(task)}% complete</span>${taskProgressBar(task)}</a>`).join('')}${group.count>4?`<a class="text-link" href="${go('tasks')}">View ${group.count-4} more</a>`:''}</div>`;
}
function dashboardDeadlineRows(items, state) {
  if (state.loading) return '<div class="empty-state">Loading deadlines...</div>';
  if (state.error) return `<div class="empty-state">${esc(state.error)}</div>`;
  if (!items.length) return '<div class="dashboard-empty"><span class="empty-icon">-</span><strong>No deadlines in this range</strong><p>Tasks with due dates will appear here. Overdue open tasks are included in this week view.</p></div>';
  const today = new Date(); today.setHours(0,0,0,0);
  return `<div class="task-list">${items.map(task=>{const overdue=new Date(task.dueDate)<today&&task.status!=='Completed';return `<div class="task-row"><span class="deadline-dot ${overdue?'overdue':''}" aria-hidden="true"></span><a href="${go('task',task.id)}"><span class="task-name">${esc(task.title)}</span><span class="task-sub">${esc(task.project.name)} &middot; ${overdue?'Overdue':formatProjectDate(task.dueDate,{month:'short',day:'numeric'})}</span></a>${tag(overdue?'Overdue':task.status,overdue?'rose':statusClass(task.status))}</div>`;}).join('')}</div>`;
}
function dashboard() {
  const state=dashboardCache||{loading:true},data=state.data||{},firstName=authUser?.name?.trim().split(/\s+/)[0]||'there';
  const projects=data.projects||[],stats=data.stats||{},groups=data.taskGroups||{};
  const statCards=[['Total projects',stats.totalProjects,'Projects you can access','P'],['Total tasks',stats.totalTasks,'Across selected projects','T'],['Completed tasks',stats.completedTasks,'Finished work','C'],['Pending tasks',stats.pendingTasks,'Still to do or in progress','O']];
  const projectRows=state.loading?'<div class="empty-state">Loading your projects...</div>':state.error?`<div class="empty-state">${esc(state.error)}</div>`:projects.length?projects.slice(0,4).map(project=>`<a class="project-row" href="${go('project',project.id)}"><div><div class="project-title">${esc(project.name)}</div><div class="project-meta">${project.taskCount} ${project.taskCount===1?'task':'tasks'}${project.deadline?` &middot; Due ${formatProjectDate(project.deadline,{month:'short',day:'numeric'})}`:''}</div></div>${tag(project.status,statusClass(project.status))}<div class="project-progress"><div class="progress-label"><span>Progress</span><strong>${project.progress}%</strong></div><div class="progress"><span style="width:${project.progress}%"></span></div></div></a>`).join('')||'<div class="dashboard-empty"><span class="empty-icon">P</span><strong>No project progress to show</strong><p>Create a project to start planning work with your team.</p></div>':'<div class="dashboard-empty"><span class="empty-icon">P</span><strong>No projects yet</strong><p>Create a project to start planning work with your team.</p></div>';
  const projectOptions=projects.map(project=>`<option value="${project.id}" ${dashboardFilters.project===project.id?'selected':''}>${esc(project.name)}</option>`).join('');
  const actions=`<button class="button" onclick="openTaskModal()">+ New task</button><button class="button primary" onclick="openProjectModal()">+ New project</button>`;
  return `${pageHead(`Good morning, ${esc(firstName)}`,'Here is what is happening across your workspace.',actions)}${state.error?`<div class="notice dashboard-notice" role="alert">${esc(state.error)} <button class="text-link" onclick="refreshDashboard()">Try again</button></div>`:''}<div class="toolbar dashboard-toolbar"><label class="subtitle" for="dashboard-project-filter">Project</label><select class="select" id="dashboard-project-filter" aria-label="Filter dashboard by project"><option value="">All accessible projects</option>${projectOptions}</select><label class="subtitle" for="dashboard-range-filter">Deadlines</label><select class="select" id="dashboard-range-filter" aria-label="Filter deadline range"><option value="week" ${dashboardFilters.range==='week'?'selected':''}>This week + overdue</option><option value="month" ${dashboardFilters.range==='month'?'selected':''}>This month + overdue</option><option value="all" ${dashboardFilters.range==='all'?'selected':''}>All dates</option><option value="overdue" ${dashboardFilters.range==='overdue'?'selected':''}>Overdue only</option></select></div><div class="grid stats">${statCards.map(([label,value,note,icon])=>`<article class="card stat-card"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${state.loading||state.error?'...':(value??0)}</div><div class="stat-note">${state.loading?'Loading':state.error?'Unavailable':note}</div></article>`).join('')}</div><div class="grid overview-grid"><section class="card panel"><div class="panel-heading"><h2>Project progress</h2><a class="text-link" href="${go('projects')}">View all</a></div><div class="project-list">${projectRows}</div></section><section class="card panel"><div class="panel-heading"><h2>Upcoming deadlines</h2><a class="text-link" href="${go('tasks')}">View tasks</a></div>${dashboardDeadlineRows(data.upcomingTasks||[],state)}</section></div><section class="card panel dashboard-status-panel"><div class="panel-heading"><h2>Tasks by status</h2><a class="text-link" href="${go('tasks')}">View all</a></div>${state.loading?'<div class="empty-state">Loading task groups...</div>':state.error?`<div class="empty-state">${esc(state.error)}</div>`:`<div class="dashboard-status-grid">${['To Do','In Progress','Completed'].map(status=>`<section class="dashboard-status"><div class="dashboard-status-heading">${tag(status,statusClass(status))}<strong>${groups[status]?.count||0}</strong></div>${dashboardTaskRows(groups[status])}</section>`).join('')}</div>`}</section><section class="card panel activity-panel"><div class="panel-heading"><h2>Recent activity</h2></div><div class="dashboard-empty"><span class="empty-icon">i</span><strong>Activity tracking is not available yet</strong><p>TaskFlow does not currently store an activity history, so there are no recorded updates to show.</p></div></section>`;
}
function projects() { const state=projectCache.get('list');return `${pageHead('Projects','Plan together and keep every initiative moving.',`<button class="button primary" onclick="openProjectModal()">＋ New project</button>`)}<div class="toolbar"><input class="search" id="project-search" value="${esc(projectSearchText)}" placeholder="⌕  Search projects" aria-label="Search projects"><select class="select" id="project-filter" aria-label="Filter projects"><option value="all" ${projectStatusFilter==='all'?'selected':''}>All statuses</option><option ${projectStatusFilter==='In progress'?'selected':''}>In progress</option><option ${projectStatusFilter==='Planning'?'selected':''}>Planning</option><option ${projectStatusFilter==='On hold'?'selected':''}>On hold</option><option ${projectStatusFilter==='Completed'?'selected':''}>Completed</option></select></div><div class="grid project-cards" id="project-grid">${projectGridContents(state)}</div>`; }
function projectGridContents(state){if(!state||state.loading)return '<div class="empty-state">Loading projects…</div>';if(state.error)return `<div class="empty-state">${esc(state.error)}</div>`;return state.items.length?state.items.map(projectCard).join(''):'<div class="empty-state">No projects match your search.</div>';}
function projectDetail(id) { const state=projectCache.get(`project:${id}`);if(!state||state.loading)return `${pageHead('Project details','Loading project…','')}<section class="card panel empty-state">Loading project details…</section>`;if(state.error)return `${pageHead('Project details','Unable to load this project.','')}<section class="card panel empty-state">${esc(state.error)}<p style="margin-top:12px"><a class="text-link" href="${go('projects')}">Back to projects</a></p></section>`;const p=state.project,owner=p.owner,tasksState=projectTaskCache.get(id);const actions=`${p.canManage?`<button class="button" onclick="openProjectModal('${p.id}')">Edit project</button><button class="button" onclick="deleteProject('${p.id}')">Delete</button>`:''}${p.canManage?`<button class="button primary" onclick="openTaskModal('', '${p.id}')">＋ New task</button>`:''}`;const dateValue=value=>value?formatProjectDate(value,{year:'numeric',month:'short',day:'numeric'}):'Not set';return `${pageHead(`<span class="detail-title"><span class="project-symbol">${esc(p.name.slice(0,1).toUpperCase())}</span>${esc(p.name)}</span>`,`Project · Updated ${dateValue(p.updatedAt)}`,actions)}<div class="grid detail-layout"><section class="card panel"><div class="detail-section"><h2>About this project</h2><p class="detail-copy">${esc(p.description||'No description has been added.')}</p></div><div class="detail-section"><div class="panel-heading"><h2>Tasks</h2>${p.canManage?`<button class="button" onclick="openTaskModal('', '${p.id}')">＋ Add task</button>`:''}</div>${taskRowsApi(tasksState?.tasks||[],tasksState)}</div></section><aside class="card panel"><div class="detail-section"><h2>Project details</h2><div class="info-list"><div class="info-line"><span>Status</span><strong>${tag(p.status,statusClass(p.status))}</strong></div><div class="info-line"><span>Start date</span><strong>${dateValue(p.startDate)}</strong></div><div class="info-line"><span>Deadline</span><strong>${dateValue(p.deadline)}</strong></div><div class="info-line"><span>Owner</span><strong>${esc(owner.name)}</strong></div></div></div><div class="detail-section"><div class="panel-heading"><h2>Project members</h2>${p.canManage?'<button class="button" onclick="openAddMemberModal()">＋ Add</button>':''}</div><div class="member-line">${avatar(initials(owner.name))}<span>${esc(owner.name)}<small class="member-role">Owner</small></span></div>${p.members.map((member,i)=>`<div class="member-line">${avatar(initials(member.name),['','purple','teal'][i%3])}<span>${esc(member.name)}<small class="member-role">${esc(member.email)}</small></span>${p.canManage?`<button class="member-remove" aria-label="Remove ${esc(member.name)}" title="Remove member" onclick="removeProjectMember('${p.id}','${member.id}')">×</button>`:''}</div>`).join('')||'<p class="subtitle" style="margin-top:12px">No other members yet.</p>'}</div></aside></div>`; }
function taskRowsApi(items,state){if(!state||state.loading)return '<div class="empty-state">Loading project tasks…</div>';if(state.error)return `<div class="empty-state">${esc(state.error)}</div>`;return items.length?`<div class="task-list">${items.map(t=>`<div class="task-row"><span class="check" aria-hidden="true"></span><a href="${go('task',t.id)}"><span class="task-name">${esc(t.title)}</span><span class="task-sub">Assigned to ${esc(t.assignee?.name||'Unassigned')} · ${t.dueDate?formatProjectDate(t.dueDate,{month:'short',day:'numeric'}):'No due date'}</span><span class="task-progress-summary">${taskProgress(t)}% complete</span>${taskProgressBar(t)}</a>${tag(t.status,statusClass(t.status))}</div>`).join('')}</div>`:'<div class="empty-state">No tasks in this project yet.</div>';}
function tasks() { const state=taskCache.get('list'),projectsState=projectCache.get('list');return `${pageHead('My tasks','A focused view of the work on your plate.',`<button class="button primary" onclick="openTaskModal()">＋ New task</button>`)}<div class="toolbar"><input class="search" id="task-search" value="${esc(taskFilters.q)}" placeholder="⌕  Search tasks" aria-label="Search tasks"><select class="select" id="task-filter" aria-label="Filter tasks"><option value="">All statuses</option>${['To Do','In Progress','Completed'].map(x=>`<option ${taskFilters.status===x?'selected':''}>${x}</option>`).join('')}</select><select class="select" id="task-priority-filter" aria-label="Filter priority"><option value="">All priorities</option>${['High','Medium','Low'].map(x=>`<option ${taskFilters.priority===x?'selected':''}>${x}</option>`).join('')}</select><select class="select" id="task-project-filter" aria-label="Filter project"><option value="">All projects</option>${(projectsState?.items||[]).map(p=>`<option value="${p.id}" ${taskFilters.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select class="select" id="task-assignee-filter" aria-label="Filter assignee"><option value="">Any assignee</option><option value="unassigned" ${taskFilters.assignee==='unassigned'?'selected':''}>Unassigned</option>${[...new Map((projectsState?.items||[]).flatMap(p=>[p.owner,...p.members]).map(u=>[u.id,u])).values()].map(u=>`<option value="${u.id}" ${taskFilters.assignee===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><section class="card panel table-wrap"><table id="task-table"><thead><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Progress</th><th>Priority</th><th>Status</th><th>Due date</th></tr></thead><tbody>${taskRowsTable(state?.tasks||[],state)}</tbody></table></section>`; }
function taskRowsTable(items,state){if(!state||state.loading)return '<tr><td colspan="7" class="empty-state">Loading tasks…</td></tr>';if(state.error)return `<tr><td colspan="7" class="empty-state">${esc(state.error)}</td></tr>`;return items.length?items.map(t=>`<tr><td><a class="task-table-title" href="${go('task',t.id)}">${esc(t.title)}</a></td><td><a href="${go('project',t.project.id)}">${esc(t.project.name)}</a></td><td>${esc(t.assignee?.name||'Unassigned')}</td><td><div class="task-table-progress"><span>${taskProgress(t)}%</span>${taskProgressBar(t)}</div></td><td>${tag(t.priority,priorityClass(t.priority))}</td><td>${tag(t.status,statusClass(t.status))}</td><td>${t.dueDate?formatProjectDate(t.dueDate,{month:'short',day:'numeric',year:'numeric'}):'—'}</td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">No tasks match these filters.</td></tr>';}
function taskDetail(id) { const state=taskCache.get(`task:${id}`);if(!state||state.loading)return `${pageHead('Task details','Loading task…','')}<section class="card panel empty-state">Loading task details…</section>`;if(state.error)return `${pageHead('Task details','Unable to load this task.','')}<section class="card panel empty-state">${esc(state.error)}<p><a class="text-link" href="${go('tasks')}">Back to tasks</a></p></section>`;const t=state.task,actions=`${t.canManage?`<button class="button" onclick="openTaskModal('${t.id}')">Edit task</button><button class="button" onclick="deleteTask('${t.id}')">Delete</button>`:''}`;return `${pageHead('Task details',`From <a class="text-link" href="${go('project',t.project.id)}">${esc(t.project.name)}</a>`,actions)}<div class="grid detail-layout"><section class="card panel"><div class="detail-section"><div class="detail-title"><h1>${esc(t.title)}</h1></div><p class="detail-copy" style="margin-top:14px">${esc(t.description||'No description has been added.')}</p></div><div class="detail-section"><div class="panel-heading"><h2>Subtasks (${t.subtasks.filter(s=>s.completed).length}/${t.subtasks.length})</h2>${t.canManage?`<button class="button" onclick="addSubtask('${t.id}')">＋ Add subtask</button>`:''}</div>${t.subtasks.length?t.subtasks.map(s=>`<div class="task-row"><input type="checkbox" ${s.completed?'checked':''} ${t.canEdit?'':'disabled'} aria-label="Complete ${esc(s.title)}" onchange="updateSubtask('${t.id}','${s.id}',{completed:this.checked})"><span class="task-name ${s.completed?'subtask-done':''}">${esc(s.title)}</span>${t.canManage?`<button class="member-remove" title="Remove subtask" onclick="deleteSubtask('${t.id}','${s.id}')">×</button>`:''}</div>`).join(''):'<p class="subtitle">No subtasks yet.</p>'}</div></section><aside class="card panel"><div class="detail-section"><h2>Task properties</h2>${taskProgressPanel(t)}<div class="info-list"><div class="info-line"><span>Status</span><strong>${t.canEdit?`<select class="select" aria-label="Task status" onchange="updateTaskStatus('${t.id}',this.value)">${['To Do','In Progress','Completed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select>`:tag(t.status,statusClass(t.status))}</strong></div><div class="info-line"><span>Priority</span><strong>${tag(t.priority,priorityClass(t.priority))}</strong></div><div class="info-line"><span>Assignee</span><strong>${esc(t.assignee?.name||'Unassigned')}</strong></div><div class="info-line"><span>Due date</span><strong>${t.dueDate?formatProjectDate(t.dueDate,{year:'numeric',month:'short',day:'numeric'}):'Not set'}</strong></div><div class="info-line"><span>Project</span><strong><a href="${go('project',t.project.id)}">${esc(t.project.name)}</a></strong></div></div></div></aside></div>`; }
function assistant() {
  ensureAssistantPage();
  const breakdown = aiMode === 'breakdown';
  const availableProjects = aiState.projects;
  const availableTasks = aiState.tasks;
  const projectSelect = document.querySelector('#ai-project')?.value || availableProjects[0]?.id || '';
  const taskSelect = document.querySelector('#ai-task')?.value || availableTasks[0]?.id || '';
  const options = breakdown
    ? availableTasks.map(t => `<option value="${t.id}" ${t.id === taskSelect ? 'selected' : ''}>${esc(t.title)} · ${esc(t.project.name)}</option>`).join('')
    : availableProjects.map(p => `<option value="${p.id}" ${p.id === projectSelect ? 'selected' : ''}>${esc(p.name)}</option>`).join('');
  let items = '';
  if (aiState.loadingResources) items = '<div class="empty-state">Loading your projects and tasks…</div>';
  else if (aiState.error) items = `<div class="notice" role="alert">${esc(aiState.error)}${!aiState.loaded?'<button class="text-link" onclick="retryAssistantResources()"> Retry</button>':''}</div>`;
  else if (aiState.loading) items = '<div class="empty-state">Generating suggestions…</div>';
  else if (aiState.results.length) items = aiState.results.map((item, i) => `<article class="ai-result">
    <label class="ai-result-check"><input type="checkbox" onchange="updateAiItem(${i},'selected',this.checked)" ${item.selected ? 'checked' : ''}><span>Include</span></label>
    <div class="field"><label for="ai-title-${i}">${breakdown ? 'Subtask' : 'Task'} title</label><input id="ai-title-${i}" value="${esc(item.title)}" minlength="2" maxlength="160" oninput="updateAiItem(${i},'title',this.value)"></div>
    ${breakdown ? '' : `<div class="field"><label for="ai-description-${i}">Description</label><textarea id="ai-description-${i}" maxlength="3000" oninput="updateAiItem(${i},'description',this.value)">${esc(item.description)}</textarea></div><div class="field"><label for="ai-priority-${i}">Priority</label><select id="ai-priority-${i}" onchange="updateAiItem(${i},'priority',this.value)">${['Low','Medium','High'].map(p => `<option ${item.priority === p ? 'selected' : ''}>${p}</option>`).join('')}</select></div>`}
    </article>`).join('');
  else if (breakdown && !availableTasks.length) items = `<div class="dashboard-empty"><span class="empty-icon">☷</span><strong>No project tasks available</strong><p>Task Breakdown works on tasks in projects you own or have joined. Ask a project owner to add you to a project with tasks.</p><a class="text-link" href="${go('projects')}">Open projects →</a> <button class="text-link" type="button" onclick="retryAssistantResources()">Refresh list</button></div>`;
  else if (!breakdown && !availableProjects.length) items = `<div class="dashboard-empty"><span class="empty-icon">✳</span><strong>No projects available</strong><p>Join a project or create one before generating task suggestions.</p><a class="text-link" href="${go('projects')}">Open projects →</a> <button class="text-link" type="button" onclick="retryAssistantResources()">Refresh list</button></div>`;
  else items = `<div class="dashboard-empty"><span class="empty-icon">✳</span><strong>${breakdown ? 'Break down a task into practical subtasks' : 'Generate tasks from a project description'}</strong><p>${breakdown ? 'Choose a task in a project you belong to to create a reviewable breakdown.' : 'Choose a project you belong to with a description to create reviewable task ideas.'}</p></div>`;
  const selectedCount = aiState.results.filter(item => item.selected).length;
  const emptyLabel = breakdown ? 'No project tasks available' : 'No projects available';
  return `${pageHead('AI Assistant','Generate task ideas, then choose what belongs in your workspace.','')}<div class="grid ai-layout"><aside class="card ai-tabs"><h3>Tools</h3><button class="ai-tab ${!breakdown?'active':''}" onclick="setAiMode('suggestions')">✳ <span>Task Suggestions</span></button><button class="ai-tab ${breakdown?'active':''}" onclick="setAiMode('breakdown')">☷ <span>Task Breakdown</span></button></aside><section class="card ai-chat"><div class="ai-chat-head"><strong>${breakdown?'AI Task Breakdown':'AI Task Suggestions'}</strong><span>AI output is a draft. Review and select items before saving.</span></div><div class="notice">${breakdown?'The selected task title and description are sent to the configured AI provider.':'The selected project name, description, and existing task titles are sent to the configured AI provider.'} Generated content is not saved until you select it.</div><div class="ai-messages" id="ai-messages">${items}</div><form class="ai-input" id="ai-form"><label class="subtitle" for="${breakdown?'ai-task':'ai-project'}">${breakdown?'Task':'Project'}</label><select class="select" id="${breakdown?'ai-task':'ai-project'}" ${!options || aiState.loadingResources ? 'disabled' : ''}>${options || `<option value="">${emptyLabel}</option>`}</select><button class="button primary" type="submit" ${aiState.loading || aiState.loadingResources || !options ? 'disabled' : ''}>${aiState.loading?'Working…':breakdown?'Generate breakdown':'Suggest tasks'}</button></form>${aiState.results.length?`<div class="ai-save-bar"><span>${selectedCount} selected</span><button id="ai-save-approved" class="button primary" type="button" onclick="saveAiApproved()" ${selectedCount?'':'disabled'}>Save selected ${breakdown?'subtasks':'tasks'}</button></div>`:''}</section></div>`;
}
function profile() { return `${pageHead('Profile & settings','Manage your personal details and preferences.','')}<div class="grid detail-layout"><section class="card panel"><div class="panel-heading"><h2>Personal information</h2></div><form id="profile-form" class="form-grid"><div class="field"><label for="full-name">Full name</label><input id="full-name" value="${esc(authUser?.name||'')}" required minlength="2" maxlength="80"></div><div class="field"><label for="profile-email">Email address</label><input id="profile-email" type="email" value="${esc(authUser?.email||'')}" disabled></div><div class="field"><label for="job-title">Job title</label><input id="job-title" value="${esc(authUser?.jobTitle||'')}" maxlength="100"></div><div class="field"><label>Role</label><input value="${esc(authUser?.role||'Team Member')}" disabled></div><div class="field full"><label for="bio">About</label><textarea id="bio" maxlength="500">${esc(authUser?.bio||'')}</textarea></div><div class="field full"><button class="button primary" style="justify-self:start">Save changes</button></div><div class="field full" id="profile-feedback" aria-live="polite"></div></form></section><aside class="card panel"><div class="detail-section"><h2>Account</h2><div class="info-list"><div class="info-line"><span>Name</span><strong>${esc(authUser?.name||'')}</strong></div><div class="info-line"><span>Email</span><strong>${esc(authUser?.email||'')}</strong></div><div class="info-line"><span>Role</span><strong>${esc(authUser?.role||'Team Member')}</strong></div></div></div></aside></div>`; }
function landing() { return `<div class="landing"><nav class="landing-nav"><a class="brand" href="${go('home')}"><span class="brand-mark">t</span>taskflow</a><div class="landing-links"><a href="#features">Features</a><a href="${go('login')}">Log in</a><a class="button primary" href="${go('register')}">Get started</a></div></nav><section class="landing-hero"><div class="eyebrow">A clearer way to work together</div><h1>Good work happens when work flows.</h1><p>Bring projects, tasks, and your team into one calm, focused workspace. Plan clearly, move confidently, and make room for the work that matters.</p><div class="landing-actions"><a class="button primary" href="${go('register')}">Get started for free →</a><a class="button" href="${go('login')}">Sign in</a></div></section><div class="landing-preview"><div class="preview-bar"><i class="preview-dot"></i><i class="preview-dot"></i><i class="preview-dot"></i></div><div class="preview-grid">${[1,2,3].map((_,i)=>`<div class="preview-card"><div class="preview-line short" style="background:${i===0?'#e9eaff':'#eceef3'}"></div><div class="preview-line"></div><div class="preview-line short"></div><div style="margin-top:22px" class="progress"><span style="width:${[68,42,82][i]}%"></span></div><div class="preview-line short" style="margin-top:15px"></div></div>`).join('')}</div></div><section class="landing-features" id="features"><div class="eyebrow">Everything in sync</div><h2>Make progress feel simple</h2><div class="grid feature-grid">${[['▣','Projects with purpose','Keep goals, people, and progress together.'],['☷','Tasks with context','Make ownership and next steps easy to see.'],['✳','AI planning support','Explore task ideas and practical breakdowns.']].map(([i,h,p])=>`<article class="feature-card"><span class="stat-icon">${i}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section></div>`; }
function auth(register=false) { return `<div class="auth-page"><aside class="auth-aside"><a class="brand" href="${go('home')}"><span class="brand-mark">t</span>taskflow</a><div class="auth-quote"><blockquote>“A little more clarity makes room for a lot more good work.”</blockquote><p>Plan, collaborate, and move forward together.</p></div><p class="subtitle">TaskFlow · Make work flow</p></aside><main class="auth-main"><form class="auth-form" id="auth-form"><h1>${register?'Create your account':'Welcome back'}</h1><p>${register?'Start organizing your work with TaskFlow.':'Sign in to continue to your workspace.'}</p>${register?'<div class="field"><label for="auth-name">Full name</label><input id="auth-name" autocomplete="name" placeholder="Your name" required></div>':''}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" type="email" autocomplete="email" placeholder="you@company.com" required></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 8 characters':'Enter your password'}" required minlength="8"></div>${register?'<label class="subtitle" style="display:flex;align-items:center;gap:7px;margin:2px 0 12px"><input type="checkbox" required> I agree to the terms and privacy policy</label>':'<div style="text-align:right;margin:0 0 12px"><a class="text-link" href="#" onclick="event.preventDefault();toast(\'Password recovery will be available soon.\')">Forgot password?</a></div>'}<button class="button primary">${register?'Create account':'Sign in'}</button><div class="auth-switch">${register?'Already have an account?':'New to TaskFlow?'} <a href="${go(register?'login':'register')}">${register?'Sign in':'Create an account'}</a></div><div class="auth-switch">Account access is handled securely by the TaskFlow server.</div></form></main></div>`; }
function render() { const parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean), route=parts[0]||'home', id=parts[1]||''; document.title=`${routes[route]||'TaskFlow'} · TaskFlow`; const protectedRoutes=['dashboard','projects','project','tasks','task','assistant','profile']; if(protectedRoutes.includes(route)&&verifiedHash!==location.hash){if(authCheckPath===location.hash)return;const requested=location.hash;authCheckPath=requested;const generation=++authGeneration;publishPage('<main class="auth-main"><p class="subtitle">Checking your session…</p></main>');fetch(`${API_BASE}/api/auth/me`,{credentials:'include'}).then(async response=>{const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Sign in to continue.');return data.user;}).then(user=>{if(generation!==authGeneration)return;if(authUser?.id!==user.id){dashboardCache=null;dashboardRequest++;dashboardFilters={project:'',range:'week'};projectCache.clear();projectTaskCache.clear();taskCache.clear();aiState={loading:false,loadingResources:false,loaded:false,error:"",projects:[],tasks:[],results:[]};}authUser=user;verifiedHash=requested;authCheckPath=null;if(location.hash===requested)render();}).catch(()=>{if(generation!==authGeneration)return;authUser=null;dashboardCache=null;projectCache.clear();projectTaskCache.clear();taskCache.clear();authCheckPath=null;sessionStorage.setItem('taskflow-next',requested);location.hash='#/login';});return;} let html; switch(route){case 'dashboard':html=frame(route,dashboard());break;case 'projects':html=frame(route,projects());break;case 'project':html=frame(route,projectDetail(decodeURIComponent(id)));break;case 'tasks':html=frame(route,tasks());break;case 'task':html=frame(route,taskDetail(id));break;case 'assistant':html=frame(route,assistant());break;case 'profile':html=frame(route,profile());break;case 'login':html=auth(false);break;case 'register':html=auth(true);break;default:html=landing();} publishPage(html); if(route==='dashboard')ensureDashboardPage();if(route==='projects'||route==='project')ensureProjectPage(route,id);if(route==='tasks')ensureTaskPage();if(route==='task')ensureTaskDetail(id);if(route==='project')ensureProjectTasks(id); }
function publishPage(html) { window.dispatchEvent(new CustomEvent('taskflow:page', { detail: html })); }
function bindPage() { document.querySelector('#dashboard-project-filter')?.addEventListener('change',filterDashboard);document.querySelector('#dashboard-range-filter')?.addEventListener('change',filterDashboard);document.querySelector('#project-search')?.addEventListener('input',filterProjects);document.querySelector('#project-filter')?.addEventListener('change',filterProjects);document.querySelector('#task-search')?.addEventListener('input',filterTasks);document.querySelector('#task-filter')?.addEventListener('change',filterTasks);document.querySelector('#task-priority-filter')?.addEventListener('change',filterTasks);document.querySelector('#task-project-filter')?.addEventListener('change',filterTasks);document.querySelector('#task-assignee-filter')?.addEventListener('change',filterTasks);document.querySelector('#ai-form')?.addEventListener('submit',sendPrompt);document.querySelector('#logout-button')?.addEventListener('click',logout);document.querySelector('#profile-form')?.addEventListener('submit',saveProfile);document.querySelector('#auth-form')?.addEventListener('submit',submitAuth); }
async function apiRequest(path,options={}){const response=await fetch(`${API_BASE}${path}`,{...options,credentials:'include',headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});const isJson=(response.headers.get('content-type')||'').includes('application/json');const data=isJson?await response.json():{};if(!isJson)throw new Error('The TaskFlow API returned an invalid response. Restart the backend, then retry.');if(!response.ok){const error=new Error(data.error||'The request could not be completed.');error.status=response.status;if(response.status===401){sessionStorage.setItem('taskflow-next',location.hash);location.hash='#/login';}throw error;}return data;}
function projectListPath(){const query=new URLSearchParams();if(projectSearchText.trim())query.set('q',projectSearchText.trim());if(projectStatusFilter!=='all')query.set('status',projectStatusFilter);return `/api/projects${query.size?`?${query}`:''}`;}
function ensureProjectPage(route,id){const key=route==='projects'?'list':`project:${id}`;if(projectCache.has(key))return;projectCache.set(key,{loading:true});const requested=location.hash;const path=route==='projects'?projectListPath():`/api/projects/${encodeURIComponent(id)}`;apiRequest(path).then(data=>projectCache.set(key,route==='projects'?{items:data.projects}:{project:data.project})).catch(error=>projectCache.set(key,{error:error.message})).finally(()=>{if(location.hash===requested)render();});}
function ensureDashboardPage(force=false){if(dashboardCache&&!force)return;dashboardCache={loading:true};const requested=location.hash,sequence=++dashboardRequest,query=new URLSearchParams();if(dashboardFilters.project)query.set('project',dashboardFilters.project);query.set('range',dashboardFilters.range);apiRequest(`/api/dashboard?${query}`).then(data=>{if(sequence===dashboardRequest)dashboardCache={data};}).catch(error=>{if(sequence===dashboardRequest)dashboardCache={error:error.message};}).finally(()=>{if(sequence===dashboardRequest&&location.hash===requested)render();});}
function filterDashboard(){dashboardFilters={project:document.querySelector('#dashboard-project-filter')?.value||'',range:document.querySelector('#dashboard-range-filter')?.value||'week'};dashboardCache=null;ensureDashboardPage(true);render();}
function refreshDashboard(){dashboardCache=null;ensureDashboardPage(true);render();}
function taskListPath(){const query=new URLSearchParams();Object.entries(taskFilters).forEach(([key,value])=>{if(value)query.set(key,value);});return `/api/tasks${query.size?`?${query}`:''}`;}
function ensureTaskPage(){if(!projectCache.has('list'))ensureProjectPage('projects','');if(taskCache.has('list'))return;taskCache.set('list',{loading:true});const requested=location.hash;apiRequest(taskListPath()).then(data=>taskCache.set('list',{tasks:data.tasks})).catch(error=>taskCache.set('list',{error:error.message})).finally(()=>{if(location.hash===requested)render();});}
function ensureTaskDetail(id){const key=`task:${id}`;if(taskCache.has(key))return;taskCache.set(key,{loading:true});const requested=location.hash;apiRequest(`/api/tasks/${encodeURIComponent(id)}`).then(data=>taskCache.set(key,{task:data.task})).catch(error=>taskCache.set(key,{error:error.message})).finally(()=>{if(location.hash===requested)render();});}
function ensureProjectTasks(id){if(projectTaskCache.has(id))return;projectTaskCache.set(id,{loading:true});const requested=location.hash;apiRequest(`/api/tasks?project=${encodeURIComponent(id)}`).then(data=>projectTaskCache.set(id,{tasks:data.tasks})).catch(error=>projectTaskCache.set(id,{error:error.message})).finally(()=>{if(location.hash===requested)render();});}
async function submitAuth(event){event.preventDefault();const form=event.currentTarget,register=location.hash.startsWith('#/register'),button=form.querySelector('button[type="submit"],button:not([type])');const errorBox=document.querySelector('#auth-error');if(errorBox)errorBox.remove();button.disabled=true;button.textContent=register?'Creating account…':'Signing in…';const payload={email:form.querySelector('#auth-email').value.trim(),password:form.querySelector('#auth-password').value};if(register)payload.name=form.querySelector('#auth-name').value.trim();try{const response=await fetch(`${API_BASE}/api/auth/${register?'register':'login'}`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(payload)});const contentType=response.headers.get('content-type')||'';if(!contentType.includes('application/json'))throw new Error('The TaskFlow API returned a webpage instead of JSON. Start the backend with npm start in the backend folder, then retry.');const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to sign in.');dashboardCache=null;dashboardRequest++;projectCache.clear();projectTaskCache.clear();taskCache.clear();aiState={loading:false,loadingResources:false,loaded:false,error:"",projects:[],tasks:[],results:[]};authUser=result.user;const next=sessionStorage.getItem('taskflow-next');sessionStorage.removeItem('taskflow-next');const safeNext=next&&/^#\/(dashboard|projects|project\/[^/]+|tasks|task\/[^/]+|assistant|profile)$/.test(next)?next:'#/dashboard';verifiedHash=safeNext;authCheckPath=null;location.hash=safeNext;}catch(error){const message=error instanceof TypeError?'Cannot reach the TaskFlow API. Start the backend with npm start in the backend folder, then retry.':error.message;showFormError(form,message);}finally{if(button.isConnected){button.disabled=false;button.textContent=register?'Create account':'Sign in';}}}
function showFormError(form,message){let box=form.querySelector('#auth-error');if(!box){box=document.createElement('p');box.id='auth-error';box.className='form-error';box.setAttribute('role','alert');form.querySelector('h1').after(box);}box.textContent=message;}
async function logout(){try{const response=await fetch(`${API_BASE}/api/auth/logout`,{method:'POST',credentials:'include'});if(!response.ok)toast('The server could not confirm sign out.');}catch{toast('Could not reach the server to confirm sign out.');}finally{authUser=null;dashboardCache=null;dashboardRequest++;dashboardFilters={project:'',range:'week'};projectCache.clear();projectTaskCache.clear();taskCache.clear();aiState={loading:false,loadingResources:false,loaded:false,error:"",projects:[],tasks:[],results:[]};verifiedHash=null;authCheckPath=null;sessionStorage.removeItem('taskflow-next');location.hash='#/login';}}
async function saveProfile(event){event.preventDefault();const form=event.currentTarget,feedback=document.querySelector('#profile-feedback'),button=form.querySelector('button');button.disabled=true;feedback.textContent='Saving…';try{const response=await fetch(`${API_BASE}/api/auth/me`,{method:'PATCH',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({name:form.querySelector('#full-name').value,jobTitle:form.querySelector('#job-title').value,bio:form.querySelector('#bio').value})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save profile.');authUser=result.user;verifiedHash=location.hash;render();toast('Profile updated.');}catch(error){feedback.textContent=error.message;feedback.className='form-error';}finally{button.disabled=false;}}
async function filterProjects(){const grid=document.querySelector('#project-grid');if(!grid)return;const sequence=++projectSearchRequest;projectSearchText=document.querySelector('#project-search').value.trim();projectStatusFilter=document.querySelector('#project-filter').value;grid.innerHTML='<div class="empty-state">Searching projects…</div>';try{const data=await apiRequest(projectListPath());if(sequence!==projectSearchRequest)return;projectCache.set('list',{items:data.projects});grid.innerHTML=projectGridContents({items:data.projects});}catch(error){if(sequence!==projectSearchRequest)return;grid.innerHTML=`<div class="empty-state">${esc(error.message)}</div>`;}}
async function filterTasks(){taskFilters={q:document.querySelector('#task-search')?.value.trim()||'',status:document.querySelector('#task-filter')?.value||'',priority:document.querySelector('#task-priority-filter')?.value||'',project:document.querySelector('#task-project-filter')?.value||'',assignee:document.querySelector('#task-assignee-filter')?.value||''};const sequence=++taskSearchRequest;const tbody=document.querySelector('#task-table tbody');if(!tbody)return;tbody.innerHTML='<tr><td colspan="6" class="empty-state">Filtering tasks…</td></tr>';try{const data=await apiRequest(taskListPath());if(sequence!==taskSearchRequest)return;taskCache.set('list',{tasks:data.tasks});tbody.innerHTML=taskRowsTable(data.tasks,{tasks:data.tasks});}catch(error){if(sequence!==taskSearchRequest)return;tbody.innerHTML=`<tr><td colspan="6" class="empty-state">${esc(error.message)}</td></tr>`;}}
function toggleSidebar(){document.querySelector('#sidebar')?.classList.toggle('open');}
function toggleTheme(){themeMode=themeMode==='dark'?'light':'dark';document.documentElement.dataset.theme=themeMode;try{localStorage.setItem('taskflow-theme',themeMode);}catch{}const button=document.querySelector('#theme-toggle');if(button){const label=`Switch to ${themeMode==='dark'?'light':'dark'} mode`;button.textContent=themeMode==='dark'?'☀':'☾';button.setAttribute('aria-label',label);button.title=label;}}
function ensureAssistantPage(){if(aiState.loadingResources||aiState.loaded||aiState.error)return;aiState.loadingResources=true;aiState.error='';const hash=location.hash,request=++aiResourceRequest;Promise.all([apiRequest('/api/projects'),apiRequest('/api/tasks')]).then(([projects,tasks])=>{if(request!==aiResourceRequest)return;aiState.projects=projects.projects;aiState.tasks=tasks.tasks;aiState.loaded=true;}).catch(error=>{if(request===aiResourceRequest)aiState.error=error.message;}).finally(()=>{if(request!==aiResourceRequest)return;aiState.loadingResources=false;if(location.hash===hash)render();});}
function refreshAssistantResources(){aiResourceRequest++;aiState={loading:false,loadingResources:false,loaded:false,error:'',projects:[],tasks:[],results:[],targetId:''};}
function retryAssistantResources(){refreshAssistantResources();ensureAssistantPage();render();}
function setAiMode(mode){aiMode=mode;aiState.results=[];aiState.targetId='';aiState.error='';render();}
function updateAiItem(index,key,value){if(!aiState.results[index])return;aiState.results[index][key]=value;const button=document.querySelector('#ai-save-approved');if(button)button.disabled=!aiState.results.some(item=>item.selected);const count=document.querySelector('.ai-save-bar span');if(count)count.textContent=`${aiState.results.filter(item=>item.selected).length} selected`;}
async function sendPrompt(e){e.preventDefault();if(aiState.loading)return;const breakdown=aiMode==='breakdown',selected=document.querySelector(breakdown?'#ai-task':'#ai-project')?.value;if(!selected){aiState.error=breakdown?'Choose a task in one of your projects before generating a breakdown.':'Choose one of your projects before generating suggestions.';render();return;}aiState.loading=true;aiState.error='';aiState.results=[];aiState.targetId=selected;render();try{const data=await apiRequest(breakdown?'/api/ai/breakdown':'/api/ai/suggestions',{method:'POST',body:JSON.stringify(breakdown?{taskId:selected}:{projectId:selected})});aiState.results=(breakdown?data.subtasks:data.suggestions).map(item=>({...item,selected:false}));if(!aiState.results.length)aiState.error='The AI provider returned no suggestions. Try again.';}catch(error){aiState.error=error.message;aiState.targetId='';}finally{aiState.loading=false;render();}}
async function saveAiApproved(){const approved=aiState.results.filter(item=>item.selected);if(!approved.length)return;const breakdown=aiMode==='breakdown',targetId=aiState.targetId;const button=document.querySelector('#ai-save-approved');if(button)button.disabled=true;try{await apiRequest(breakdown?'/api/ai/breakdown/approve':'/api/ai/suggestions/approve',{method:'POST',body:JSON.stringify(breakdown?{taskId:targetId,subtasks:approved.map(({title})=>({title:title.trim()}))}:{projectId:targetId,suggestions:approved.map(({title,description,priority})=>({title:title.trim(),description:description.trim(),priority}))})});aiState.results=aiState.results.filter(item=>!item.selected);if(!aiState.results.length)aiState.targetId='';if(breakdown){taskCache.delete('list');const data=await apiRequest('/api/tasks/'+encodeURIComponent(targetId));taskCache.set('task:'+targetId,{task:data.task});}else{taskCache.delete('list');projectTaskCache.delete(targetId);dashboardCache=null;}toast(approved.length+' approved '+(breakdown?'subtask':'task')+(approved.length===1?'':'s')+' saved.');render();}catch(error){if(button?.isConnected)button.disabled=false;toast(error.message);}}
async function openTaskModal(taskId='',projectId=''){let task=taskId?taskCache.get(`task:${taskId}`)?.task:null;if(taskId&&!task){toast('Task details are still loading.');return;}let projects;try{projects=(await apiRequest('/api/projects')).projects;}catch(error){toast(error.message);return;}if(taskId&&!task.canManage){const previous=task.status;const choice=window.prompt(`Update status (${['To Do','In Progress','Completed'].join(' / ')})`,previous);if(!choice||choice===previous)return;if(!['To Do','In Progress','Completed'].includes(choice)){toast('Choose a valid task status.');return;}return updateTaskStatus(taskId,choice);}const manageableProjects=projects.filter(p=>p.canManage);const selectedProject=projectId||task?.project.id||manageableProjects[0]?.id;if(!selectedProject){toast('You need project management access to create tasks.');return;}let project;try{project=(await apiRequest(`/api/projects/${encodeURIComponent(selectedProject)}`)).project;}catch(error){toast(error.message);return;}const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.id='modal-backdrop';const due=task?.dueDate?new Date(task.dueDate).toISOString().slice(0,10):'';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="task-modal-title"><div class="modal-head"><h2 id="task-modal-title">${task?'Edit task':'Create a task'}</h2><button class="close-button" aria-label="Close" onclick="closeModal()">×</button></div><form id="task-form"><div class="form-grid"><div class="field full"><label for="task-title-input">Task name</label><input id="task-title-input" minlength="2" maxlength="160" required value="${esc(task?.title||'')}" placeholder="e.g. Review project brief"></div><div class="field full"><label for="task-description-input">Description</label><textarea id="task-description-input" maxlength="3000" placeholder="Add context for the team">${esc(task?.description||'')}</textarea></div><div class="field"><label for="task-project-input">Project</label><select id="task-project-input" ${taskId?'disabled':''}>${manageableProjects.map(p=>`<option value="${p.id}" ${p.id===selectedProject?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="task-status-input">Status</label><select id="task-status-input">${['To Do','In Progress','Completed'].map(s=>`<option ${task?.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="task-priority-input">Priority</label><select id="task-priority-input">${['Low','Medium','High'].map(s=>`<option ${task?.priority===s?'selected':(!task&&s==='Medium')?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="task-due-input">Due date</label><input id="task-due-input" type="date" value="${due}"></div><div class="field full"><label for="task-assignee-input">Assignee</label><select id="task-assignee-input"><option value="">Unassigned</option>${[project.owner,...project.members].map(u=>`<option value="${u.id}" ${task?.assignee?.id===u.id?'selected':''}>${esc(u.name)} · ${esc(u.email)}</option>`).join('')}</select></div></div><div id="task-form-error" class="form-error" role="alert" hidden></div><div class="form-actions"><button type="button" class="button" onclick="closeModal()">Cancel</button><button class="button primary">${task?'Save changes':'Create task'}</button></div></form></section>`;document.body.appendChild(overlay);overlay.addEventListener('click',e=>{if(e.target===overlay)closeModal();});document.querySelector('#task-form').addEventListener('submit',e=>saveTask(e,taskId));document.querySelector('#task-title-input').focus();}
async function saveTask(event,id=''){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"],button:not([type])'),errorBox=document.querySelector('#task-form-error');button.disabled=true;errorBox.hidden=true;const payload={title:form.querySelector('#task-title-input').value,description:form.querySelector('#task-description-input').value,project:form.querySelector('#task-project-input').value,status:form.querySelector('#task-status-input').value,priority:form.querySelector('#task-priority-input').value,dueDate:form.querySelector('#task-due-input').value||null,assignee:form.querySelector('#task-assignee-input').value||null};try{const result=await apiRequest(id?`/api/tasks/${encodeURIComponent(id)}`:'/api/tasks',{method:id?'PATCH':'POST',body:JSON.stringify(payload)});const task=result.task;dashboardCache=null;taskCache.set(`task:${task.id}`,{task});taskCache.delete('list');projectTaskCache.delete(task.project.id);closeModal();toast(id?'Task updated.':'Task created.');if(location.hash.startsWith('#/tasks')&&!id)await ensureTaskRefresh();else if(location.hash===go('task',id)||location.hash.startsWith('#/project/'))render();else location.hash=go('task',task.id);}catch(error){errorBox.textContent=error.message;errorBox.hidden=false;}finally{button.disabled=false;}}
async function ensureTaskRefresh(){try{const data=await apiRequest(taskListPath());taskCache.set('list',{tasks:data.tasks});render();}catch(error){toast(error.message);}}
async function updateTaskStatus(id,status){const task=taskCache.get(`task:${id}`)?.task;if(!task)return;try{const data=await apiRequest(`/api/tasks/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status})});dashboardCache=null;taskCache.set(`task:${id}`,{task:data.task});taskCache.delete('list');projectTaskCache.delete(task.project.id);render();toast('Task status updated.');}catch(error){toast(error.message);}}
async function deleteTask(id){if(!window.confirm('Delete this task? This cannot be undone.'))return;try{await apiRequest(`/api/tasks/${encodeURIComponent(id)}`,{method:'DELETE'});const task=taskCache.get(`task:${id}`)?.task;dashboardCache=null;taskCache.delete(`task:${id}`);taskCache.delete('list');if(task)projectTaskCache.delete(task.project.id);location.hash=go('tasks');toast('Task deleted.');}catch(error){toast(error.message);}}
async function addSubtask(id){const title=window.prompt('Subtask name');if(!title)return;try{const data=await apiRequest(`/api/tasks/${encodeURIComponent(id)}/subtasks`,{method:'POST',body:JSON.stringify({title})});taskCache.set(`task:${id}`,{task:data.task});dashboardCache=null;taskCache.delete('list');projectTaskCache.delete(data.task.project.id);render();}catch(error){toast(error.message);}}
async function updateSubtask(id,subtaskId,fields){try{const data=await apiRequest(`/api/tasks/${encodeURIComponent(id)}/subtasks/${encodeURIComponent(subtaskId)}`,{method:'PATCH',body:JSON.stringify(fields)});taskCache.set(`task:${id}`,{task:data.task});dashboardCache=null;taskCache.delete('list');projectTaskCache.delete(data.task.project.id);render();}catch(error){toast(error.message);render();}}
async function deleteSubtask(id,subtaskId){if(!window.confirm('Remove this subtask?'))return;try{const data=await apiRequest(`/api/tasks/${encodeURIComponent(id)}/subtasks/${encodeURIComponent(subtaskId)}`,{method:'DELETE'});taskCache.set(`task:${id}`,{task:data.task});dashboardCache=null;taskCache.delete('list');projectTaskCache.delete(data.task.project.id);render();}catch(error){toast(error.message);}}
function closeModal(){document.querySelector('#modal-backdrop')?.remove();}
function toast(text){document.querySelector('#toast')?.remove();const el=document.createElement('div');el.id='toast';el.textContent=text;el.style.cssText='position:fixed;z-index:30;bottom:22px;left:50%;transform:translateX(-50%);padding:11px 16px;background:#252b35;color:white;border-radius:8px;font-size:11px;box-shadow:0 7px 22px #151b2530';document.body.appendChild(el);setTimeout(()=>el.remove(),2600);}
function initials(name=''){return name.split(/\s+/).filter(Boolean).map(part=>part[0]).slice(0,2).join('').toUpperCase()||'?';}
function formatProjectDate(value,options){const dateText=String(value).slice(0,10),parts=dateText.split('-').map(Number);if(parts.length!==3||parts.some(Number.isNaN))return 'Not set';return new Date(parts[0],parts[1]-1,parts[2]).toLocaleDateString(undefined,options);}
function openProjectModal(id=''){const current=id?projectCache.get(`project:${id}`)?.project:null;if(id&&!current){toast('Project details are still loading.');return;}const editing=Boolean(current),dateField=value=>value?new Date(value).toISOString().slice(0,10):'';const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.id='modal-backdrop';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="project-modal-title"><div class="modal-head"><h2 id="project-modal-title">${editing?'Edit project':'Create a project'}</h2><button class="close-button" aria-label="Close" onclick="closeModal()">×</button></div><form id="project-form"><div class="form-grid"><div class="field full"><label for="project-name">Project name</label><input id="project-name" minlength="2" maxlength="120" required value="${esc(current?.name||'')}" placeholder="e.g. Website redesign"></div><div class="field full"><label for="project-description">Description</label><textarea id="project-description" maxlength="2000" placeholder="What is this project about?">${esc(current?.description||'')}</textarea></div><div class="field"><label for="project-start">Start date</label><input id="project-start" type="date" value="${dateField(current?.startDate)}"></div><div class="field"><label for="project-deadline">Deadline</label><input id="project-deadline" type="date" value="${dateField(current?.deadline)}"></div><div class="field"><label for="project-status">Status</label><select id="project-status">${['Planning','In progress','On hold','Completed'].map(status=>`<option ${current?.status===status?'selected':''}>${status}</option>`).join('')}</select></div></div><div id="project-form-error" class="form-error" role="alert" hidden></div><div class="form-actions"><button type="button" class="button" onclick="closeModal()">Cancel</button><button class="button primary">${editing?'Save changes':'Create project'}</button></div></form></section>`;document.body.appendChild(overlay);overlay.addEventListener('click',event=>{if(event.target===overlay)closeModal();});document.querySelector('#project-form').addEventListener('submit',event=>saveProject(event,id));document.querySelector('#project-name').focus();}
async function saveProject(event,id=''){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"],button:not([type])'),errorBox=document.querySelector('#project-form-error');button.disabled=true;errorBox.hidden=true;const payload={name:form.querySelector('#project-name').value,description:form.querySelector('#project-description').value,status:form.querySelector('#project-status').value,startDate:form.querySelector('#project-start').value||null,deadline:form.querySelector('#project-deadline').value||null};try{const result=await apiRequest(id?`/api/projects/${encodeURIComponent(id)}`:'/api/projects',{method:id?'PATCH':'POST',body:JSON.stringify(payload)});const project=result.project;dashboardCache=null;projectCache.delete('list');projectCache.set(`project:${project.id}`,{project});closeModal();toast(id?'Project updated.':'Project created.');if(!id)location.hash=go('project',project.id);else render();}catch(error){errorBox.textContent=error.message;errorBox.hidden=false;}finally{button.disabled=false;}}
function openAddMemberModal(){const route=location.hash.split('/'),id=route[2];if(!id)return;const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.id='modal-backdrop';overlay.innerHTML='<section class="modal" role="dialog" aria-modal="true" aria-labelledby="member-modal-title"><div class="modal-head"><h2 id="member-modal-title">Add a project member</h2><button class="close-button" aria-label="Close" onclick="closeModal()">×</button></div><form id="member-form"><div class="field"><label for="member-email">Account email</label><input id="member-email" type="email" required maxlength="254" placeholder="teammate@company.com"></div><div id="member-form-error" class="form-error" role="alert" hidden></div><div class="form-actions"><button type="button" class="button" onclick="closeModal()">Cancel</button><button class="button primary">Add member</button></div></form></section>';document.body.appendChild(overlay);overlay.addEventListener('click',event=>{if(event.target===overlay)closeModal();});document.querySelector('#member-form').addEventListener('submit',event=>addProjectMember(event,id));document.querySelector('#member-email').focus();}
async function addProjectMember(event,id){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"],button:not([type])'),errorBox=document.querySelector('#member-form-error');button.disabled=true;errorBox.hidden=true;try{const result=await apiRequest(`/api/projects/${encodeURIComponent(id)}/members`,{method:'POST',body:JSON.stringify({email:form.querySelector('#member-email').value.trim()})});dashboardCache=null;projectCache.set(`project:${id}`,{project:result.project});closeModal();render();toast('Member added.');}catch(error){errorBox.textContent=error.message;errorBox.hidden=false;}finally{button.disabled=false;}}
async function removeProjectMember(id,userId){if(!window.confirm('Remove this person from the project?'))return;try{const result=await apiRequest(`/api/projects/${encodeURIComponent(id)}/members/${encodeURIComponent(userId)}`,{method:'DELETE'});dashboardCache=null;projectCache.set(`project:${id}`,{project:result.project});render();toast('Member removed.');}catch(error){toast(error.message);}}
async function deleteProject(id){if(!window.confirm('Delete this project? This cannot be undone.'))return;try{await apiRequest(`/api/projects/${encodeURIComponent(id)}`,{method:'DELETE'});dashboardCache=null;projectCache.delete(`project:${id}`);projectCache.delete('list');location.hash=go('projects');toast('Project deleted.');}catch(error){toast(error.message);}}
window.__taskflowBindPage = bindPage;
window.renderTaskFlowPage = render;
let assistantRouteActive=location.hash.replace(/^#\/?/,'').split('/')[0]==='assistant';window.addEventListener('hashchange',()=>{const isAssistant=location.hash.replace(/^#\/?/,'').split('/')[0]==='assistant';if(isAssistant&&!assistantRouteActive)refreshAssistantResources();assistantRouteActive=isAssistant;render();});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});render();
